- id: C-15-items-036
  kind: relic
  own_name: 'реликвия: усиленный ульта'
  numbers:
    damage_and_speed: 0.2
    drain_mod: -0.3
    drain_priority: 5
    pool_tier: 4
    base_price: 5
  behavior: 'Пока активен режим ульты (шкала дошла до 100): урон (кроме статусных) и скорость движения +20 % (итог ×1.2). Постоянно:
    убывание шкалы в активном режиме −30 % (итог ×0.7; приоритет 5), т.е. режим длится дольше.'
  source_ref: BuffWithOverdrive (BuffWithOverdrive.cs)
  tags:
  - Атака

--CODE
using System;

public class BuffWithOverdrive : Item
{
	public static string staticID = "BuffWithOverdrive";

	private static float statInc = 0.2f;

	private NumVarStatMod buffMod;

	private NumVarStatMod odDecayMod;

	protected override string ExtraInfo => PercentToStr(statInc, "+");

	public BuffWithOverdrive()
	{
		ID = staticID;
		category = Category.Offense;
		buffMod = new NumVarStatMod(ID, 0f, 10, VarStatModType.Multiplicative);
		odDecayMod = new NumVarStatMod(ID, -0.3f, 5, VarStatModType.Multiplicative);
	}

	public override void Activate()
	{
		SetEventHandlers(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetEventHandlers(givenStatus: false);
	}

	private void SetEventHandlers(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			StatManager.ModifyAllStatData(buffMod, parentSkillCategory, StatData.damageStr, IgnoreStatusConditional, givenStatus);
			parentPlayer.overdriveActiveDecayRate.Modify(odDecayMod, givenStatus);
			OnOverdriveEvent(givenStatus && parentPlayer.overdriveReady);
			Player player = parentPlayer;
			player.overdriveEventHandlers = (Player.OverdriveEvent)Delegate.Remove(player.overdriveEventHandlers, new Player.OverdriveEvent(OnOverdriveEvent));
			if (givenStatus)
			{
				Player player2 = parentPlayer;
				player2.overdriveEventHandlers = (Player.OverdriveEvent)Delegate.Combine(player2.overdriveEventHandlers, new Player.OverdriveEvent(OnOverdriveEvent));
			}
			else
			{
				RemoveFromItemBar();
			}
		}
	}

	private void OnOverdriveEvent(bool ready, bool timedOut = false)
	{
		UpdateMod(ready);
		UpdateItemBar(ready ? ItemStatusBar.ItemState.Active : ItemStatusBar.ItemState.Disabled);
	}

	private void UpdateMod(bool givenStatus)
	{
		if (!(parentPlayer == null))
		{
			buffMod.modValue = ((!givenStatus) ? 0f : statInc);
			parentPlayer.movement.moveSpeedStat.Modify(buffMod, givenStatus);
		}
	}
}

