--CODE
using System;

public class CapDamageItem : Item
{
	public static string staticID = "CapDamageItem";

	private NumVarStatMod capDamageMod;

	private float healthPercentCap = 0.1f;

	public CapDamageItem()
	{
		ID = staticID;
		category = Category.Defense;
		capDamageMod = new NumVarStatMod(ID, -1f, 10, VarStatModType.Override);
	}

	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}

	private void SetModStatus(bool givenStatus)
	{
		if (!(parentEntity == null))
		{
			ApplyMod(givenStatus);
			NumVarStat healthStat = parentEntity.health.healthStat;
			healthStat.statChangedEventHandlers = (VarStat<float>.StatChangedEventHandler)Delegate.Remove(healthStat.statChangedEventHandlers, new VarStat<float>.StatChangedEventHandler(OnHealthChange));
			if (givenStatus)
			{
				NumVarStat healthStat2 = parentEntity.health.healthStat;
				healthStat2.statChangedEventHandlers = (VarStat<float>.StatChangedEventHandler)Delegate.Combine(healthStat2.statChangedEventHandlers, new VarStat<float>.StatChangedEventHandler(OnHealthChange));
			}
		}
	}

	private void OnHealthChange()
	{
		if (parentEntity != null)
		{
			ApplyMod(givenStatus: true);
		}
	}

	private void ApplyMod(bool givenStatus)
	{
		if (givenStatus)
		{
			capDamageMod.modValue = (int)(healthPercentCap * parentEntity.health.healthStat.ModifiedValue);
		}
		parentEntity.health.damageCapStat.Modify(capDamageMod, givenStatus);
	}
}

