public class CritUpAtLowHealth : ModWithHP
{
	public static string staticID = "CritUpAtLowHealth";

	protected override string ExtraInfo => PercentToStr(0.2f, "+");

	public CritUpAtLowHealth()
	{
		ID = staticID;
		category = Category.Offense;
		comparisonType = IntComparisonType.LessThanEquals;
		HPThreshold = PlayerStatusBar.healthBlinkThreshold;
		statMod = new NumVarStatMod(ID, 0f);
	}

	public override void Activate()
	{
		SetModStatus(givenStatus: true);
		base.Activate();
	}

	public override void Deactivate()
	{
		base.Deactivate();
		SetModStatus(givenStatus: false);
	}

	public override void ActivatePowerup()
	{
		base.ActivatePowerup();
		UpdateMod(givenStatus: true);
		UpdateItemBar(ItemStatusBar.ItemState.Active);
	}

	public override void DeactivatePowerup()
	{
		base.DeactivatePowerup();
		UpdateMod(givenStatus: false);
		UpdateItemBar(ItemStatusBar.ItemState.Disabled);
	}

	private void SetModStatus(bool givenStatus)
	{
		StatManager.ModifyAllStatData(statMod, parentSkillCategory, "criticalHitChance", IgnoreStatusConditional, givenStatus);
		if (givenStatus)
		{
			UpdateItemBar(ItemStatusBar.ItemState.Disabled);
		}
		else
		{
			RemoveFromItemBar();
		}
	}

	private void UpdateMod(bool givenStatus)
	{
		statMod.modValue = ((!givenStatus) ? 0f : 0.2f);
	}
}

