- id: C-15-items-061
  kind: relic
  own_name: 'Реликвия: урон при полном здоровье'
  numbers:
    урон_множ:
      value: 0.2
      unit: доля
    порог_здоровья:
      value: 1.0
      unit: доля макс. HP
  behavior: В момент подбора один раз восстанавливает здоровье владельца до максимума. Пока здоровье не ниже максимума, урон всех арканов, кроме статусных, увеличен на 20 % (итог ×1.2). При потере хотя бы единицы здоровья бонус выключается, при возврате к максимуму включается снова. При выбросе реликвия безвозвратно исчезает, игроку показывается уведомление о потере.
  source_ref: DamageUpAtMaxHealth (DamageUpAtMaxHealth.cs)

--CODE
using UnityEngine;

public class DamageUpAtMaxHealth : ModWithHP
{
	public static string staticID = "DamageUpAtMaxHealth";

	private NumVarStatMod damageMod;

	protected override string ExtraInfo => PercentToStr(damageMod, "+");

	public DamageUpAtMaxHealth()
	{
		ID = staticID;
		category = Category.Offense;
		destroyOnDrop = true;
		comparisonType = IntComparisonType.GreaterThanEquals;
		HPThreshold = 1f;
		damageMod = new NumVarStatMod(ID, 0.2f, 10, VarStatModType.Multiplicative);
	}

	public override void Activate()
	{
		if (SetParentAsPlayer())
		{
			parentPlayer.health.RestoreHealth(0, showDisplayText: true, playSound: true, fullyRestoreHealth: true);
			Object.Instantiate(HealthPowerup.EffectPrefab, parentPlayer.transform.position, Quaternion.identity, parentPlayer.transform);
		}
		UpdateItemBar(ItemStatusBar.ItemState.Disabled);
		base.Activate();
	}

	public override void Deactivate()
	{
		base.Deactivate();
		RemoveFromItemBar();
		if (parentPlayer != null)
		{
			parentPlayer.newItemNoticeUI.Display(TextManager.GetItemName(ID), IconManager.GetItemIcon(ID), null, isSkill: false, isSignature: false, isEmpowered: false, acquired: false);
		}
	}

	public override void ActivatePowerup()
	{
		base.ActivatePowerup();
		UpdateItemBar(ItemStatusBar.ItemState.Active);
		SetModStatus();
	}

	public override void DeactivatePowerup()
	{
		base.DeactivatePowerup();
		UpdateItemBar(ItemStatusBar.ItemState.Disabled);
		SetModStatus(givenStatus: false);
	}

	private void SetModStatus(bool givenStatus = true)
	{
		StatManager.ModifyAllStatData(damageMod, parentSkillCategory, StatData.damageStr, IgnoreStatusConditional, givenStatus);
	}
}

