using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class DamageUpWithMapReveal : Item
{
	public static string staticID = "DamageUpWithMapReveal";

	private static Dictionary<int, float> idDamageDict = new Dictionary<int, float>();

	private static float dmgMultiplier = 0.0004f;

	private NumVarStatMod damageMod;

	private int parentID;

	private float currentDmgVal;

	private bool itemHeld;

	private ChaosQuickStopwatch waitStopwatch = new ChaosQuickStopwatch(2f);

	private bool waitCompleted = true;

	private float BankDamageValue
	{
		get
		{
			return (!idDamageDict.ContainsKey(parentID)) ? 0f : idDamageDict[parentID];
		}
		set
		{
			idDamageDict[parentID] = value;
		}
	}

	private float CurrentDamageValue => (!NextLevelLoader.InTierScene(string.Empty)) ? 0f : (Mathf.Round(Minimap.RevealedVal * 100f) * dmgMultiplier);

	protected override string ExtraInfo => PercentToStr(damageMod, "+");

	public DamageUpWithMapReveal()
	{
		ID = staticID;
		category = Category.Offense;
		RunData.runResetEventHandlers = (RunData.RunEvent)Delegate.Remove(RunData.runResetEventHandlers, new RunData.RunEvent(OnRunReset));
		RunData.runResetEventHandlers = (RunData.RunEvent)Delegate.Combine(RunData.runResetEventHandlers, new RunData.RunEvent(OnRunReset));
		damageMod = new NumVarStatMod(ID, 0f, 10, VarStatModType.Multiplicative);
	}

	private static void OnRunReset()
	{
		idDamageDict.Clear();
	}

	public override void Activate()
	{
		SetEventHandlers(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetEventHandlers(givenStatus: false);
	}

	private void SetEventHandlers(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			parentID = parentPlayer.playerID;
			itemHeld = givenStatus;
			StatManager.ModifyAllStatData(damageMod, parentSkillCategory, StatData.damageStr, IgnoreStatusConditional, givenStatus);
			GameController.levelLoadEventHandlers = (GameController.LevelLoadEventHandler)Delegate.Remove(GameController.levelLoadEventHandlers, new GameController.LevelLoadEventHandler(OnLevelLoad));
			MinimapSection.minimapRevealEventHandlers = (MinimapSection.MinimapRevealEvent)Delegate.Remove(MinimapSection.minimapRevealEventHandlers, new MinimapSection.MinimapRevealEvent(OnMinimapReveal));
			if (givenStatus)
			{
				GameController.levelLoadEventHandlers = (GameController.LevelLoadEventHandler)Delegate.Combine(GameController.levelLoadEventHandlers, new GameController.LevelLoadEventHandler(OnLevelLoad));
				MinimapSection.minimapRevealEventHandlers = (MinimapSection.MinimapRevealEvent)Delegate.Combine(MinimapSection.minimapRevealEventHandlers, new MinimapSection.MinimapRevealEvent(OnMinimapReveal));
				UpdateMod();
			}
		}
	}

	private void UpdateMod()
	{
		damageMod.modValue = BankDamageValue + CurrentDamageValue;
	}

	private void OnLevelLoad(string aStr, string bStr)
	{
		UpdateMod();
		BankDamageValue += CurrentDamageValue;
	}

	private void OnMinimapReveal(bool actual)
	{
		if (waitCompleted && parentEntity != null)
		{
			parentEntity.StartCoroutine(QueueUpdateDamage());
		}
	}

	private IEnumerator QueueUpdateDamage()
	{
		if (!waitStopwatch.IsRunning)
		{
			waitCompleted = false;
			waitStopwatch.IsRunning = true;
			while (waitStopwatch.IsRunning)
			{
				yield return null;
			}
			if (itemHeld)
			{
				UpdateMod();
			}
			waitCompleted = true;
		}
	}
}

