using System.Collections;
using System.Collections.Generic;

public class EvadeUpOnHurt : OnTakeDamageItem
{
	public static string staticID = "EvadeUpOnHurt";

	private static Dictionary<int, int> idCDDict = new Dictionary<int, int>();

	private static float cdTime = 30f;

	private int parentID = -1;

	private NumVarStatMod evadeMod;

	private ChaosQuickStopwatch durationStopwatch = new ChaosQuickStopwatch(2.5f);

	private bool CDReady => idCDDict.ContainsKey(parentID) && ChaosStopwatch.Check(idCDDict[parentID]);

	public EvadeUpOnHurt()
	{
		ID = staticID;
		category = Category.Defense;
		activateOnActual = true;
		evadeMod = new NumVarStatMod(ID, 1f, 0, VarStatModType.Override);
	}

	public override void Activate()
	{
		base.Activate();
		if (SetParentAsPlayer())
		{
			parentID = parentPlayer.playerID;
			if (!idCDDict.ContainsKey(parentID))
			{
				idCDDict[parentID] = -1;
			}
			UpdateItemBar(CDReady ? ItemStatusBar.ItemState.Ready : ItemStatusBar.ItemState.Disabled);
		}
	}

	public override void Deactivate()
	{
		base.Deactivate();
		ApplyMod(givenStatus: false);
		RemoveFromItemBar();
	}

	public override void OnTakeDamageActual(AttackInfo givenAtkInfo, Entity givenEnt)
	{
		if (CDReady && parentEntity != null)
		{
			parentEntity.StartCoroutine(HandleCooldown(parentID));
			parentEntity.StartCoroutine(StartEvadeBuff());
		}
	}

	private IEnumerator StartEvadeBuff()
	{
		ApplyMod(givenStatus: true);
		UpdateItemBar(ItemStatusBar.ItemState.Active);
		durationStopwatch.IsRunning = true;
		while (durationStopwatch.IsRunning)
		{
			yield return null;
		}
		ApplyMod(givenStatus: false);
		UpdateItemBar(ItemStatusBar.ItemState.Disabled);
	}

	private IEnumerator HandleCooldown(int givenID)
	{
		idCDDict[givenID] = ChaosStopwatch.Begin(cdTime);
		while (!ChaosStopwatch.Check(idCDDict[givenID]))
		{
			yield return null;
		}
		UpdateItemBar(ItemStatusBar.ItemState.Ready);
	}

	private void ApplyMod(bool givenStatus)
	{
		if (parentEntity != null)
		{
			parentEntity.health.evadeStat.Modify(evadeMod, givenStatus);
		}
	}
}

