using System.Collections;
using UnityEngine;

public class FreeDashChargesOnKillChance : ModWithKills
{
	public static string staticID = "FreeDashChargesOnKillChance";

	private int chargeIncrease = 99;

	private NumVarStatMod chargeMod;

	private const float activationChance = 0.2f;

	private ChaosQuickStopwatch durationStopwatch = new ChaosQuickStopwatch(6f);

	private bool itemHeld;

	protected override string ExtraInfo => PercentToStr(0.2f, string.Empty);

	public FreeDashChargesOnKillChance()
	{
		ID = staticID;
		category = Category.Misc;
		chargeMod = new NumVarStatMod(ID, chargeIncrease, 10, VarStatModType.Override);
	}

	public override void SetExtraMods(bool givenStatus)
	{
		itemHeld = givenStatus;
		SetItemBarStatus();
	}

	private void SetItemBarStatus()
	{
		if (!itemHeld)
		{
			RemoveFromItemBar();
		}
		else if (durationStopwatch.IsRunning)
		{
			UpdateItemBar(ItemStatusBar.ItemState.Active);
		}
		else
		{
			UpdateItemBar(ItemStatusBar.ItemState.Disabled);
		}
	}

	public override void HandleKillEvent(Entity givenEntity, AttackInfo givenInfo)
	{
		if (Random.value < 0.2f && !durationStopwatch.IsRunning)
		{
			parentPlayer.StartCoroutine(BoostDashCharges());
		}
	}

	private IEnumerator BoostDashCharges()
	{
		PoolManager.GetPoolItem<ParticleEffect>("SparkleAura").Emit(7, parentPlayer.attackOriginTrans.position);
		SoundManager.PlayAudioWithDistance("MagicianSparkle", parentPlayer.attackOriginTrans.position);
		durationStopwatch.IsRunning = true;
		ModifyDashSkills(givenStatus: true);
		SetItemBarStatus();
		while (durationStopwatch.IsRunning)
		{
			yield return null;
		}
		ModifyDashSkills(givenStatus: false);
		SetItemBarStatus();
	}

	private void ModifyDashSkills(bool givenStatus)
	{
		Player.ModifySkills(parentPlayer, IsChargeDashConditional, ApplyChargeMod, givenStatus);
	}

	private bool IsChargeDashConditional(Player.SkillState givenSkill)
	{
		return givenSkill != null && givenSkill.isChargeSkill && givenSkill.isDash;
	}

	private void ApplyChargeMod(Player.SkillState givenSkill, bool givenStatus)
	{
		givenSkill.cooldownRef.maxChargeStat.Modify(chargeMod, givenStatus);
		if (givenStatus)
		{
			givenSkill.cooldownRef.Reset();
		}
		else
		{
			givenSkill.StartCooldownTimer(chargeIncrease);
		}
	}
}

