public class FrostFlameStanza : ElementalDamageUp
{
	public static string staticID = "FrostFlameStanza";

	private string fireEleStr;

	private string iceEleStr;

	private string currentSkillID;

	private string currentEleStr;

	private NumVarStatMod statusChanceMod;

	private NumVarStatMod freezeDurationMod;

	public FrostFlameStanza()
		: base(staticID, ElementType.Chaos, 0.2f)
	{
		ID = staticID;
		category = Category.Offense;
		combineOnly = true;
		fireEleStr = ElementType.Fire.ToString();
		iceEleStr = ElementType.Ice.ToString();
		statusChanceMod = new NumVarStatMod(staticID, 0.35f);
		freezeDurationMod = new NumVarStatMod(staticID, 0.5f);
	}

	private bool CheckElement(StatData givenStatData)
	{
		currentEleStr = givenStatData.GetValue<string>(ElementalDamageUp.subEleFieldStr);
		return currentEleStr == fireEleStr || currentEleStr == iceEleStr;
	}

	public override void Activate()
	{
		foreach (StatData allStatDatum in StatManager.GetAllStatData("Skills", parentSkillCategory))
		{
			if (!CheckElement(allStatDatum))
			{
				continue;
			}
			currentSkillID = allStatDatum.GetValue<string>("ID");
			if (currentSkillID.Contains("Status"))
			{
				continue;
			}
			allStatDatum.AddMod("damage", damageMod);
			if (!currentSkillID.Contains("Basic"))
			{
				if (currentEleStr == iceEleStr)
				{
					allStatDatum.AddMod("freezeChance", statusChanceMod);
					allStatDatum.AddMod("freezeDuration", freezeDurationMod);
				}
				else
				{
					allStatDatum.AddMod("burnChance", statusChanceMod);
				}
			}
		}
	}

	public override void Deactivate()
	{
		foreach (StatData allStatDatum in StatManager.GetAllStatData("Skills", parentSkillCategory))
		{
			if (CheckElement(allStatDatum))
			{
				allStatDatum.RemoveMod("damage", damageMod.ID);
				allStatDatum.RemoveMod("burnChance", statusChanceMod.ID);
				allStatDatum.RemoveMod("freezeChance", statusChanceMod.ID);
				allStatDatum.RemoveMod("freezeDuration", freezeDurationMod.ID);
			}
		}
	}
}

