	{
		if (!(parentEntity == null) && givenAtkInfo != null)
		{
			goldDropAmount = (int)((float)givenAtkInfo.damage * Random.Range(minRatio, maxRatio));
			if (goldDropAmount > 0)
			{
				LootManager.DropGold(parentEntity.transform.position, goldDropAmount);
