	private void SetEventHandlers(bool givenStatus)
	{
		if (givenStatus && SetParentAsPlayer() && parentPlayer.inventory.ContainsItem(Vampiricism.staticID))
		{
			parentPlayer.inventory.AddItem(VampireSet.staticID, showNotice: false, ignoreMax: true);
