			parentPlayer.inventory.RemoveItem(staticID, forceOverride: true);
			return;
		}
		Attack.globalCritEventHandlers = (Attack.CritEventHandler)Delegate.Remove(Attack.globalCritEventHandlers, new Attack.CritEventHandler(OnCritEvent));
		if (givenStatus)
		{
			Attack.globalCritEventHandlers = (Attack.CritEventHandler)Delegate.Combine(Attack.globalCritEventHandlers, new Attack.CritEventHandler(OnCritEvent));
		}
	}

	private void OnCritEvent(AttackInfo attackInfo, Entity atkEntity = null, Entity hurtEntity = null)
	{
		if (attackInfo != null && !(attackInfo.skillCategory != parentSkillCategory) && !(hurtEntity is Pinata) && !(hurtEntity is Destructible) && parentEntity != null && !parentEntity.fsm.currentStateName.Contains("Dead") && parentEntity.health.CurrentHealthValue > 0)
		{
			parentEntity.health.RestoreHealth(1);
		}
	}
}

