public class HealRestock : Item
{
	public static string staticID = "HealRestock";

	private ItemMerchant curItemMerchant;

	private HealStoreItem newHealItem;

	public HealRestock()
	{
		ID = staticID;
		category = Category.Misc;
		combineOnly = true;
	}

	public override void Activate()
	{
		HealStoreItem.buyEventHandlers = (HealStoreItem.BuyEventHandler)Delegate.Remove(HealStoreItem.buyEventHandlers, new HealStoreItem.BuyEventHandler(OnBuyEvent));
		HealStoreItem.buyEventHandlers = (HealStoreItem.BuyEventHandler)Delegate.Combine(HealStoreItem.buyEventHandlers, new HealStoreItem.BuyEventHandler(OnBuyEvent));
	}

	public override void Deactivate()
	{
		HealStoreItem.buyEventHandlers = (HealStoreItem.BuyEventHandler)Delegate.Remove(HealStoreItem.buyEventHandlers, new HealStoreItem.BuyEventHandler(OnBuyEvent));
	}

	private void OnBuyEvent(HealStoreItem healItem)
	{
		if (!(healItem == null) && healItem.allowRestock && !(healItem.parentNpc == null))
		{
			if (healItem.priceMarker != null && healItem.priceMarker.gameObject != null)
			{
