using System;

public class MeleeCritChanceUp : Item
{
	public static string staticID = "MeleeCritChanceUp";

	private NumVarStatMod critMod;

	private bool itemHeld;

	public MeleeCritChanceUp()
	{
		ID = staticID;
		category = Category.Offense;
		critMod = new NumVarStatMod(ID, 2f, 10, VarStatModType.LateMultiplicative);
	}

	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}

	private void SetModStatus(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			itemHeld = givenStatus;
			SetItemBarStatus();
			Player.ModifySkills(critMod, parentPlayer, StatData.critChStr, MeleeConditional, givenStatus);
			Player player = parentPlayer;
			player.assignSkillSlotEventHandlers = (Player.AssignSkillSlotEventHandler)Delegate.Remove(player.assignSkillSlotEventHandlers, new Player.AssignSkillSlotEventHandler(OnSkillAssigned));
			if (givenStatus)
			{
				Player player2 = parentPlayer;
				player2.assignSkillSlotEventHandlers = (Player.AssignSkillSlotEventHandler)Delegate.Combine(player2.assignSkillSlotEventHandlers, new Player.AssignSkillSlotEventHandler(OnSkillAssigned));
			}
		}
	}

	private void OnSkillAssigned(Player.SkillState givenSkill, int givenSlot)
	{
		SetItemBarStatus();
	}

	private void SetItemBarStatus()
	{
		if (!itemHeld)
		{
			RemoveFromItemBar();
		}
		else if (HasMeleeSkill())
		{
			UpdateItemBar(ItemStatusBar.ItemState.Active);
		}
		else
		{
			UpdateItemBar(ItemStatusBar.ItemState.Disabled);
		}
	}

	private bool HasMeleeSkill()
	{
		for (int i = 0; i < parentPlayer.assignedSkills.Length; i++)
		{
			if (MeleeConditional(parentPlayer.assignedSkills[i]))
			{
				return true;
			}
		}
		return false;
	}

	private bool MeleeConditional(Player.SkillState givenSkill)
	{
		return givenSkill?.isMeleeSkill ?? false;
	}
}

