public class OverdriveMaxAtLowHealth : ModWithHP
{
	public static string staticID = "OverdriveMaxAtLowHealth";

	private static string fieldID = "overdriveProgressMultiplier";

	private static float incValue = 0.3f;

	protected override string ExtraInfo => PercentToStr(incValue, "+");

	public OverdriveMaxAtLowHealth()
	{
		ID = staticID;
		category = Category.Misc;
		comparisonType = IntComparisonType.LessThanEquals;
		HPThreshold = PlayerStatusBar.healthBlinkThreshold;
		statMod = new NumVarStatMod(ID, 0f, 10, VarStatModType.Multiplicative);
	}

	public override void Activate()
	{
		UpdateItemBar(ItemStatusBar.ItemState.Disabled);
		SetModStatus(givenStatus: true);
		base.Activate();
	}

	public override void Deactivate()
	{
		base.Deactivate();
		SetModStatus(givenStatus: false);
		RemoveFromItemBar();
	}

	public override void ActivatePowerup()
	{
		base.ActivatePowerup();
		UpdateMod(givenStatus: true);
		UpdateItemBar(ItemStatusBar.ItemState.Active);
	}

	public override void DeactivatePowerup()
	{
		base.DeactivatePowerup();
		UpdateMod(givenStatus: false);
		UpdateItemBar(ItemStatusBar.ItemState.Disabled);
	}

	private void SetModStatus(bool givenStatus)
	{
		StatManager.ModifyAllStatData(statMod, parentSkillCategory, fieldID, IgnoreStatusConditional, givenStatus);
	}

	private void UpdateMod(bool givenStatus)
	{
		statMod.modValue = ((!givenStatus) ? 0f : incValue);
	}
}

