using System;
using System.Collections.Generic;

public class ReduceCDWithCursedRelics : Item
{
	public static string staticID = "ReduceCDWithCursedRelics";

	private static float cdInc = -0.04f;

	private static float odInc = 0.05f;

	private NumVarStatMod cdMod;

	private NumVarStatMod odMod;

	private Dictionary<string, NumVarStatMod> modDict;

	private int cursedCount;

	protected override string ExtraInfo => PercentToStr(cdMod, "-") + " | " + PercentToStr(odMod, "+");

	public ReduceCDWithCursedRelics()
	{
		ID = staticID;
		category = Category.Misc;
		parentGroupID = WithCursedRelicsGroupItem.staticID;
		cdMod = new NumVarStatMod(ID, 0f, 10, VarStatModType.Multiplicative);
		odMod = new NumVarStatMod(ID, 0f, 10, VarStatModType.Multiplicative);
		modDict = new Dictionary<string, NumVarStatMod>
		{
			{ "cooldown", cdMod },
			{ "overdriveProgressMultiplier", odMod }
		};
	}

	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}

	private void SetModStatus(bool givenStatus)
	{
		if ((!givenStatus || !GroupItemCreated(WithCursedRelicsGroupItem.staticID)) && !(parentEntity == null))
		{
			StatManager.ModifyAllStatData(modDict, parentSkillCategory, IgnoreStatusConditional, givenStatus);
			Inventory inventory = parentEntity.inventory;
			inventory.inventoryChangeEventHandler = (Inventory.ItemEventHandler)Delegate.Remove(inventory.inventoryChangeEventHandler, new Inventory.ItemEventHandler(OnInventoryChange));
			if (givenStatus)
			{
				Inventory inventory2 = parentEntity.inventory;
				inventory2.inventoryChangeEventHandler = (Inventory.ItemEventHandler)Delegate.Combine(inventory2.inventoryChangeEventHandler, new Inventory.ItemEventHandler(OnInventoryChange));
				OnInventoryChange(null, givenStatus: false);
			}
		}
	}

	private void OnInventoryChange(Item givenItem, bool givenStatus)
	{
		if (!(parentEntity == null))
		{
			cursedCount = parentEntity.inventory.CursedCount;
			cdMod.modValue = (float)cursedCount * cdInc;
			odMod.modValue = (float)cursedCount * odInc;
		}
	}
}

