using System;
using Chaos.AnimatorExtensions;
using UnityEngine;

public class ReflectShield : MonoBehaviour
{
	public delegate void ShieldBrokenEventHandler();

	private bool markedForDestroy;

	private static GameObject prefab;

	private Animator anim;

	public bool spawnAnimPlayed;

	private bool activated;

	public GameObject parentObject;

	public Entity parentEntity;

	private Rigidbody2D rigidbody2D;

	[HideInInspector]
	public NegateProjectiles reflectScript;

	private GameObject reflectObj;

	private CircleCollider2D reflectCol;

	private SpriteRenderer reflectSprite;

	public float duration;

	public float shieldScale;

	public string skillCategory;

	public float reflectDamageModifier = 1f;

	public Transform followTrans;

	public bool useDuration;

	private ChaosQuickStopwatch durationStopwatch;

	public bool useReflectCount;

	private bool waitingForRefresh;

	public int availableReflectCount = 5;

	private int ogReflectCount = 5;

	public bool useRefreshTimer;

	public float refreshTime = 5f;

	private int refreshStopwatchID = -1;

	public ShieldBrokenEventHandler shieldBrokenEventHandlers;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/EnemySkills/ReflectShield.prefab"));

	public virtual void Awake()
	{
		anim = GetComponent<Animator>();
		rigidbody2D = GetComponent<Rigidbody2D>();
		reflectObj = transform.Find("Reflect").gameObject;
		reflectScript = reflectObj.GetComponent<NegateProjectiles>();
		reflectCol = reflectObj.GetComponent<CircleCollider2D>();
		reflectSprite = reflectObj.GetComponentInChildren<SpriteRenderer>();
	}

	public virtual void Start()
	{
		reflectScript.parentObject = parentObject;
		reflectScript.transform.localScale = transform.localScale * shieldScale;
		reflectScript.damageModifier = reflectDamageModifier;
		reflectScript.skillCategory = skillCategory;
		(durationStopwatch = new ChaosQuickStopwatch(duration)).IsRunning = useDuration;
		if (useReflectCount)
		{
			NegateProjectiles negateProjectiles = reflectScript;
			negateProjectiles.reflectEventHandlers = (NegateProjectiles.ReflectEventHandler)Delegate.Combine(negateProjectiles.reflectEventHandlers, new NegateProjectiles.ReflectEventHandler(ReflectShieldHit));
		}
		SoundManager.PlayAudioWithDistance("ReflectShieldForm", transform.position);
		ogReflectCount = availableReflectCount;
	}

	public virtual void Update()
	{
		if (useRefreshTimer && waitingForRefresh)
		{
			if (ChaosStopwatch.Check(refreshStopwatchID))
			{
				waitingForRefresh = false;
				spawnAnimPlayed = false;
				if (useDuration)
				{
					(durationStopwatch = new ChaosQuickStopwatch(duration)).IsRunning = true;
				}
				if (useReflectCount)
				{
					availableReflectCount = ogReflectCount;
				}
			}
		}
		else if (!spawnAnimPlayed)
		{
			if (anim.AnimPlayed())
			{
				spawnAnimPlayed = true;
				reflectCol.enabled = true;
				anim.Play("Spawn", -1, 0f);
			}
		}
		else if (parentEntity == null || parentEntity.fsm.currentStateName.Contains("Dead") || (useDuration && !durationStopwatch.IsRunning) || (useReflectCount && availableReflectCount <= 0))
		{
			Reset();
		}
	}

	public virtual void LateUpdate()
	{
		if (followTrans != null)
		{
			rigidbody2D.MovePosition(followTrans.position);
		}
	}

	public void SetActiveStatus(bool givenStatus)
	{
		reflectSprite.enabled = givenStatus;
		reflectObj.SetActive(givenStatus);
	}

	private void ReflectShieldHit(NegateProjectiles n, Collider2D other)
	{
		availableReflectCount--;
		anim.Play("Flash", -1, 0f);
	}

	public void Reset()
	{
		if (!markedForDestroy)
		{
			reflectCol.enabled = false;
			if (shieldBrokenEventHandlers != null)
			{
				shieldBrokenEventHandlers();
			}
			anim.Play("Destroyed", -1, 0f);
			PoolManager.GetPoolItem<ParticleEffect>("GlassCircleBreakEffect").Emit(30, transform.position);
			SoundManager.PlayAudioWithDistance("ReflectShieldBreak", transform.position);
			if (useRefreshTimer)
			{
				refreshStopwatchID = ChaosStopwatch.Begin(refreshTime);
				waitingForRefresh = true;
			}
			else if (gameObject != null)
			{
				markedForDestroy = true;
				UnityEngine.Object.Destroy(gameObject, 1.5f);
			}
		}
	}
}

