using System;
using UnityEngine;

public class ResetCDChance : Item
{
	public static string staticID = "ResetCDChance";

	private static float resetChance = 0.2f;

	protected override string ExtraInfo => PercentToStr(resetChance, string.Empty);

	public ResetCDChance()
	{
		ID = staticID;
		category = Category.Misc;
	}

