	{
		SetEventHandlers(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetEventHandlers(givenStatus: false);
	}

	private void SetEventHandlers(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			CooldownManager cooldownManager = parentPlayer.cooldownManager;
			cooldownManager.startCDEventHandlers = (CooldownManager.StartCDEventHandler)Delegate.Remove(cooldownManager.startCDEventHandlers, new CooldownManager.StartCDEventHandler(ResetCD));
