using UnityEngine;

public class ResurrectRing : ResurrectItem
{
	public static string staticID = "ResurrectRing";

	private GameObject visualPrefab;

	private GameObject visualObject;

	public ResurrectRing()
	{
		ID = staticID;
		category = Category.Defense;
		isCursed = true;
		priority = 0;
		visualPrefab = ChaosBundle.Get("Assets/Prefabs/Items/ResurrectRing.prefab");
	}

	public override void Activate()
	{
		if (!(parentEntity == null))
		{
			parentEntity.health.CurrentHealthValue = Mathf.CeilToInt((float)parentEntity.health.CurrentHealthValue * 0.5f);
			AttackInfo attackInfo = new AttackInfo();
			attackInfo.skillID = ID;
			attackInfo.damage = 0;
			attackInfo.showDamageNumber = false;
			parentEntity.health.TakeDamage(attackInfo, null, critPreCalculated: true);
			visualObject = Object.Instantiate(visualPrefab, parentEntity.transform.position + Vector3.up * 2f, Quaternion.identity, parentEntity.transform);
		}
	}

	public override void Deactivate()
	{
		if (visualObject != null)
		{
			Object.Destroy(visualObject);
		}
	}
}

