using System;

public class ShieldWithOverdriveTimeOut : Item
{
	public static string staticID = "ShieldWithOverdriveTimeOut";

	private int shieldIncrease = 25;

	public ShieldWithOverdriveTimeOut()
	{
		ID = staticID;
		category = Category.Defense;
	}

	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}

	private void SetModStatus(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			Player player = parentPlayer;
			player.overdriveEventHandlers = (Player.OverdriveEvent)Delegate.Remove(player.overdriveEventHandlers, new Player.OverdriveEvent(OnOverdriveEvent));
			if (givenStatus)
			{
				Player player2 = parentPlayer;
				player2.overdriveEventHandlers = (Player.OverdriveEvent)Delegate.Combine(player2.overdriveEventHandlers, new Player.OverdriveEvent(OnOverdriveEvent));
			}
		}
	}

	private void OnOverdriveEvent(bool ready, bool timedOut = false)
	{
		if (!ready && timedOut && parentPlayer != null && Globals.InGameScene(string.Empty))
		{
			parentPlayer.health.CurrentShieldValue += shieldIncrease;
		}
	}
}

