using System;

public class SigEleDamageUp : Item
{
	public static string staticID = "SigEleDamageUp";

	private NumVarStatMod hurtMod;

	private NumVarStatMod damageUpMod;

	private NumVarStatMod damageDownMod;

	private Player.SkillState sigSkill;

	protected override string ExtraInfo => PercentToStr(damageUpMod, "+") + " | " + PercentToStr(damageDownMod, "-") + " | " + PercentToStr(hurtMod, "+");

	public SigEleDamageUp()
	{
		ID = staticID;
		category = Category.Offense;
		isCursed = true;
		hurtMod = new NumVarStatMod(ID, 0.33f, 10, VarStatModType.Multiplicative);
		damageUpMod = new NumVarStatMod(ID, 0.5f, 10, VarStatModType.Multiplicative);
		damageDownMod = new NumVarStatMod(ID, -0.5f, 10, VarStatModType.Multiplicative);
	}

	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}

	private void SetModStatus(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			sigSkill = parentPlayer.GetSignatureSkill();
			parentEntity.health.damageTakenStat.Modify(hurtMod, givenStatus);
			StatManager.ModifyAllStatData(damageUpMod, parentSkillCategory, "damage", DamageUpCheck, givenStatus);
			StatManager.ModifyAllStatData(damageDownMod, parentSkillCategory, "damage", DamageDownCheck, givenStatus);
			Player player = parentPlayer;
			player.skillPickUpEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player.skillPickUpEventHandlers, new Player.SkillEventHandler(OnSkillChange));
			Player player2 = parentPlayer;
			player2.skillDropEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player2.skillDropEventHandlers, new Player.SkillEventHandler(OnSkillChange));
			Player player3 = parentPlayer;
			player3.skillRemoveEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player3.skillRemoveEventHandlers, new Player.SkillEventHandler(OnSkillChange));
			if (givenStatus)
			{
				Player player4 = parentPlayer;
				player4.skillPickUpEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player4.skillPickUpEventHandlers, new Player.SkillEventHandler(OnSkillChange));
				Player player5 = parentPlayer;
				player5.skillDropEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player5.skillDropEventHandlers, new Player.SkillEventHandler(OnSkillChange));
				Player player6 = parentPlayer;
				player6.skillRemoveEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player6.skillRemoveEventHandlers, new Player.SkillEventHandler(OnSkillChange));
			}
		}
	}

	private bool DamageUpCheck(StatData givenStatData)
	{
		return !givenStatData.GetValue<bool>("isStatusEffect") && givenStatData.GetValue<string>("elementType") == sigSkill.element.ToString();
	}

	private bool DamageDownCheck(StatData givenStatData)
	{
		return !givenStatData.GetValue<bool>("isStatusEffect") && givenStatData.GetValue<string>("elementType") != sigSkill.element.ToString();
	}

	private void OnSkillChange(Player.SkillState givenSkill)
	{
		if (SetParentAsPlayer() && givenSkill != sigSkill)
		{
			sigSkill = parentPlayer.GetSignatureSkill();
		}
	}
}

