using System;

public class VampireSet : HeadgearItem
{
	public static string staticID = "VampireSet";

	private Enemy currentEnemy;

	private NumVarStatMod outfitPaletteMod;

	public VampireSet()
	{
		ID = staticID;
		category = Category.Defense;
		combineOnly = true;
		headgearPrefab = ChaosBundle.Get("Assets/Prefabs/Headgear/VampHat.prefab");
		outfitPaletteMod = new NumVarStatMod(ID, 22f, 3, VarStatModType.Override);
	}

	public override void Activate()
	{
		base.Activate();
		SetModStatus(givenStatus: true);
	}

	public override void Deactivate()
	{
		base.Deactivate();
		SetModStatus(givenStatus: false);
	}

	private void SetModStatus(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			parentPlayer.SetPlayerOutfitColor(outfitPaletteMod, givenStatus);
			Attack.globalCritEventHandlers = (Attack.CritEventHandler)Delegate.Remove(Attack.globalCritEventHandlers, new Attack.CritEventHandler(OnCritEvent));
			Player player = parentPlayer;
			player.absEnemyKillEventHandlers = (Player.AbsEnemyKillEventHandler)Delegate.Remove(player.absEnemyKillEventHandlers, new Player.AbsEnemyKillEventHandler(OnKillEvent));
			if (givenStatus)
			{
				Attack.globalCritEventHandlers = (Attack.CritEventHandler)Delegate.Combine(Attack.globalCritEventHandlers, new Attack.CritEventHandler(OnCritEvent));
				Player player2 = parentPlayer;
				player2.absEnemyKillEventHandlers = (Player.AbsEnemyKillEventHandler)Delegate.Combine(player2.absEnemyKillEventHandlers, new Player.AbsEnemyKillEventHandler(OnKillEvent));
			}
		}
	}

	private bool IsValidKill(Entity givenEntity, AttackInfo givenInfo)
	{
		currentEnemy = givenEntity as Enemy;
		if (currentEnemy == null || (currentEnemy is Blob && ((Blob)currentEnemy).isMini))
		{
			return false;
		}
		return !currentEnemy.summoned && currentEnemy.parentSummoner == null;
	}

	private void OnKillEvent(Entity givenEntity, AttackInfo givenInfo)
	{
		if (IsValidKill(givenEntity, givenInfo))
		{
			HandleKillEvent(givenEntity, givenInfo);
		}
	}

	private void HandleKillEvent(Entity givenEntity, AttackInfo givenInfo)
	{
		parentPlayer.health.RestoreHealth(5);
	}

	private void OnCritEvent(AttackInfo atkInfo, Entity atkEntity = null, Entity hurtEntity = null)
	{
		if (atkInfo != null && !(atkInfo.skillCategory != parentSkillCategory) && !(hurtEntity is Pinata) && !(hurtEntity is Destructible) && parentEntity != null && !parentEntity.fsm.currentStateName.Contains("Dead") && parentEntity.health.CurrentHealthValue > 0)
		{
			parentEntity.health.RestoreHealth(1);
		}
	}
}

